        print(json.dumps(t))
    print("\n=== ENDMILLS (flat) ===")
    endmills = mb.list_library_tools(contains="Endmill")
    for t in endmills:
        if "Ball" not in t["description"] and "Fly" not in t["description"]:
            print(json.dumps(t))

