def run(_context):
    import json
    import adsk.cam
    import adsk.fusion
    import adsk.core

    app = adsk.core.Application.get()
    doc = app.activeDocument

    cam = None
    for p in doc.products:
        if p.classType() == adsk.cam.CAM.classType():
            cam = adsk.cam.CAM.cast(p)

    setup = None
    for i in range(cam.setups.count):
        if cam.setups[i].name == "Setup1":
            setup = cam.setups[i]
            break

    # List current operations
    print("=== Current operations ===")
    ops_to_delete = []
    for i in range(setup.operations.count):
        op = setup.operations[i]
        try:
            print(f"  {i}: {op.name}")
            if op.name == "Face Top":
                ops_to_delete.append(op)
        except:
            print(f"  {i}: <error accessing name>")

    # Delete duplicates
    for op in ops_to_delete:
        try:
            op.deleteMe()
            print(f"Deleted: Face Top")
        except Exception as e:
            print(f"Error deleting: {e}")

    # Regenerate the full setup
    print("\n=== Regenerating setup ===")
    gen = mb.generate(setup="Setup1")
    print(json.dumps(gen, indent=2))

